(34261, 'Job 5:18', 'Job', 5, 18, 'کۀ هغه زخمى کول کوى، نو هغه يې مرهم پټۍ هم کوى، کۀ هغه وهل کوى، نو د هغۀ لاسونه يې علاج هم کوى.', 'کۀ هغه زخمی کول کوی، نو هغه یې مرهم پتی هم کوی، کۀ هغه وهل کوی، نو د هغۀ لاسونه یې علاج هم کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34262, 'Job 5:19', 'Job', 5, 19, 'هغه به تاسو د شپږو افتونو نه بچ کوى، او په اوؤم کښې به تاسو ته هيڅ نقصان نۀ رسيږى.', 'هغه به تاسو د شپزو افتونو نه بچ کوی، او په اووم کشې به تاسو ته هیچ نقصان نۀ رسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34263, 'Job 5:20', 'Job', 5, 20, 'په قحط کښې به هغه تاسو د مرګ نه په بيعه واخلى، او په جنګ کښې به مو د مرګ نه بچ کړى.', 'په قحط کشې به هغه تاسو د مرګ نه په بیعه واخلی، او په جنګ کشې به مو د مرګ نه بچ کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34264, 'Job 5:21', 'Job', 5, 21, 'تاسو به د سپکو خبرو نه بچ شئ، او چې کله تباهى راځى نو تاسو به نۀ يرېږئ.', 'تاسو به د سپکو خبرو نه بچ شی، او چې کله تباهی راجی نو تاسو به نۀ یرېزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34265, 'Job 5:22', 'Job', 5, 22, 'په تباهۍ او قحط پورې به تاسو خندا کوئ، او د زمکې د ځنګلى ځناورو نه به نۀ يرېږئ.', 'په تباهی او قحط پورې به تاسو خندا کوی، او د زمکې د جنګلی جناورو نه به نۀ یرېزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34266, 'Job 5:23', 'Job', 5, 23, 'تاسو چې کوم پټى کَرئ نو په هغې کښې به کاڼى نۀ وى، او ځنګلى ځناور به په تاسو حمله نۀ کوى.', 'تاسو چې کوم پتی کری نو په هغې کشې به کانی نۀ وی، او جنګلی جناور به په تاسو حمله نۀ کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34267, 'Job 5:24', 'Job', 5, 24, 'تاسو ته به پته ولګى چې ستاسو کور محفوظ دے، تاسو به وګورئ چې ستاسو د رَمو نه به هيڅ ورک نۀ وى.', 'تاسو ته به پته ولګی چې ستاسو کور محفوظ دے، تاسو به وګوری چې ستاسو د رمو نه به هیچ ورک نۀ وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34268, 'Job 5:25', 'Job', 5, 25, 'تاسو ته به پته ولګى چې ستاسو اولاد به ډېر وى، داسې بې‌شمېره لکه په زمکه چې واښۀ وى.', 'تاسو ته به پته ولګی چې ستاسو اولاد به دېر وی، داسې بې‌شمېره لکه په زمکه چې واشۀ وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34269, 'Job 5:26', 'Job', 5, 26, 'تاسو به خپل قبر ته په بوډاتوب کښې ځئ، لکه چې د فصل ګېډۍ درمند ته په خپل موسم کښې راځى.', 'تاسو به خپل قبر ته په بوداتوب کشې جی، لکه چې د فصل ګېدی درمند ته په خپل موسم کشې راجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34270, 'Job 5:27', 'Job', 5, 27, 'ګوره، زمونږه چې د عمر په حقله کومه تجربه ده، دا حقيقت دے. دا نصيحت واوره او په دې باندې عمل وکړه.“', 'ګوره، زمونزه چې د عمر په حقله کومه تجربه ده، دا حقیقت دے. دا نصیحت واوره او په دې باندې عمل وکره.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_5_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34271, 'Deuteronomy 8:1', 'Deuteronomy', 8, 1, 'په وفادارۍ سره د هغو ټولو قوانینو څخه پیروي وکړئ چې نن یې تاسو ته درکوم ترڅو ژوند وکړئ، شمېر مو زیات شي او هغې خاورې ته چې د هغې وعده څښتن ستاسو د نیکونو سره کړې ده، ورننوځئ او هغه ونیسئ.', 'په وفاداری سره د هغو تولو قوانینو چخه پیروی وکری چې نن یې تاسو ته درکوم ترچو ژوند وکری، شمېر مو زیات شی او هغې خاورې ته چې د هغې وعده چشتن ستاسو د نیکونو سره کرې ده، ورننوجی او هغه ونیسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34272, 'Deuteronomy 8:2', 'Deuteronomy', 8, 2, 'در په یاد کړئ چې په تېرو څلوېښتو کلونو کې ستاسو څښتن خدای څنګه تاسو ته په دښته کې په دې اوږده سفر کې لارښوونه وکړه. په تاسو باندې یې سختۍ راوستلې چې ومو ازمایي، ترڅو هغه پوه شي چې ستاسو په زړونو کې څه دي او د هغه په حکمونو باندې عمل کوئ یا نه.', 'در په یاد کری چې په تېرو چلوېشتو کلونو کې ستاسو چشتن خدای چنګه تاسو ته په دشته کې په دې اوزده سفر کې لارشوونه وکره. په تاسو باندې یې سختی راوستلې چې ومو ازمایی، ترچو هغه پوه شی چې ستاسو په زرونو کې چه دی او د هغه په حکمونو باندې عمل کوی یا نه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34273, 'Deuteronomy 8:3', 'Deuteronomy', 8, 3, 'هغه په تاسو باندې لوږه راوستله او بیا یې د خوراک دپاره من درکړ، یعنې هغه خواړه چې تاسو او ستاسو نیکونو مخکې هېڅکله خوړلي نه وو. هغه د دې دپاره دا کار وکړ چې تاسو ته دا خبره درزده کړي چې انسان یوازې په ډوډۍ نه بلکې په هره خبره باندې ژوندی دی چې د څښتن د خولې څخه راوځي.', 'هغه په تاسو باندې لوزه راوستله او بیا یې د خوراک دپاره من درکر، یعنې هغه خواره چې تاسو او ستاسو نیکونو مخکې هېچکله خورلی نه وو. هغه د دې دپاره دا کار وکر چې تاسو ته دا خبره درزده کری چې انسان یوازې په دودی نه بلکې په هره خبره باندې ژوندی دی چې د چشتن د خولې چخه راوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34274, 'Deuteronomy 8:4', 'Deuteronomy', 8, 4, 'د دغو څلوېښتو کلونو په دوران کې ستاسو کالي نه دي زاړه شوي او نه مو پښې پړسېدلې دي.', 'د دغو چلوېشتو کلونو په دوران کې ستاسو کالی نه دی زاره شوی او نه مو پشې پرسېدلې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_8_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34275, 'Deuteronomy 8:5', 'Deuteronomy', 8, 5, 'په یاد لرئ چې ستاسو څښتن خدای تاسو اصلاح کوي او داسې سزا درکوي لکه څنګه چې یو پلار خپل اولادونه اصلاح کوي.', 'په یاد لری چې ستاسو چشتن خدای تاسو اصلاح کوی او داسې سزا درکوی لکه چنګه چې یو پلار خپل اولادونه اصلاح کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34276, 'Deuteronomy 8:6', 'Deuteronomy', 8, 6, 'نو بیا هغه کار کوئ چې څښتن یې درباندې امر کړی دی، یعنې د هغه د قوانینو سره سم ژوند کوئ او د هغه څخه وېرېږئ.', 'نو بیا هغه کار کوی چې چشتن یې درباندې امر کری دی، یعنې د هغه د قوانینو سره سم ژوند کوی او د هغه چخه وېرېزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34277, 'Deuteronomy 8:7', 'Deuteronomy', 8, 7, 'ستاسو څښتن خدای تاسو یوې حاصلخېزې ځمکې یعنې داسې ځمکې ته راولي چې سیندونه او چینې لري او د ځمکې لاندې داسې ویالې لري چې اوبه یې درو او غونډیو ته راوځي،', 'ستاسو چشتن خدای تاسو یوې حاصلخېزې جمکې یعنې داسې جمکې ته راولی چې سیندونه او چینې لری او د جمکې لاندې داسې ویالې لری چې اوبه یې درو او غوندیو ته راوجی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34278, 'Deuteronomy 8:8', 'Deuteronomy', 8, 8, 'یوه داسې ځمکه چې غنم او اوربشې، انګور، انځر، انار، زیتون او شات په کې پیدا کیږي.', 'یوه داسې جمکه چې غنم او اوربشې، انګور، انجر، انار، زیتون او شات په کې پیدا کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34279, 'Deuteronomy 8:9', 'Deuteronomy', 8, 9, 'دا داسې وطن دی چې خواړه په کې پرېمانه دي او د هېڅ شي کمی په کې نشته. د دې ځای تیږې د اوسپنې څخه ډکې دي او د غونډیو څخه یې مس راویستلی شئ.', 'دا داسې وطن دی چې خواره په کې پرېمانه دی او د هېچ شی کمی په کې نشته. د دې جای تیزې د اوسپنې چخه دکې دی او د غوندیو چخه یې مس راویستلی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34280, 'Deuteronomy 8:10', 'Deuteronomy', 8, 10, 'هرڅه چې تاسو غواړئ وخورئ هغه به درورسیږي او تاسو به د هغې حاصلخېزې ځمکې دپاره چې ستاسو څښتن خدای درکړې ده د هغه شکر ادا کړئ.', 'هرچه چې تاسو غواری وخوری هغه به درورسیزی او تاسو به د هغې حاصلخېزې جمکې دپاره چې ستاسو چشتن خدای درکرې ده د هغه شکر ادا کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_8_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(34281, 'Deuteronomy 8:11', 'Deuteronomy', 8, 11, 'پام کوئ چې تاسو به هېڅکله خپل څښتن خدای نه هېروئ. هېڅکله د هغه د هغو قوانینو څخه سرغړونه ونه کړئ چې نن یې تاسو ته درکوم.', 'پام کوی چې تاسو به هېچکله خپل چشتن خدای نه هېروی. هېچکله د هغه د هغو قوانینو چخه سرغرونه ونه کری چې نن یې تاسو ته درکوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34282, 'Deuteronomy 8:12', 'Deuteronomy', 8, 12, 'کله چې تاسو ته د خوراک دپاره هرڅه درورسیږي او د اوسېدلو دپاره ښه ښه کورونه ودان کړئ', 'کله چې تاسو ته د خوراک دپاره هرچه درورسیزی او د اوسېدلو دپاره شه شه کورونه ودان کری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(34283, 'Deuteronomy 8:13', 'Deuteronomy', 8, 13, 'او کله چې ستاسو پادې او رمې، ستاسو سپین زر او سره زر او نور ټول شیان زیات شي،', 'او کله چې ستاسو پادې او رمې، ستاسو سپین زر او سره زر او نور تول شیان زیات شی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/deuteronomy_8_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
